ragraph","content":[{"type":"text","text":"Pipes in a crawl space, garage or outside wall"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A frozen outdoor tap or supply line"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Water stains after a freeze"}]}]}]}]},"button":null}},{"id":"f56f78b9-e268-4210-8eda-f8e84bcd120d","type":"contentBlock","data":{"label":"Get a faster, better match","heading":"What to Include in Your Request","imagePosition":"none","image":"","imageAlt":"","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The more detail you share, the easier it is for a professional to understand the job:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Which taps or areas have no water"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where the pipes run (outside wall, crawl space, garage)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Whether any pipe is leaking or split"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Photos of the pipe and the area"}]}]}]}]},"button":null}},{"id":"7c3e13d2-5ed4-4317-8395-62d9669b02c7","type":"steps","data":{"heading":"How to Request Service","intro":"","steps":[{"title":"Tell Us What You Need","text":"Select a service and describe the problem."},{"title":"Share the Details","text":"Add your location, preferred appointment time and photos of the issue."},{"title":"Find a Local Pro","text":"We match your request with professionals serving Denver or Boulder."},{"title":"Schedule Service","text":"Connect with the professional and arrange the appointment."}],"buttons":[{"label":"Request Service","href":"/book-service?category=plumbing&service=frozen-pipe-repair","variant":"primary"}]}},{"id":"47957273-5012-4d4a-8b79-9d7d12365e8e","type":"faq","data":{"heading":"Frequently Asked Questions","items":[{"question":"What should I do if I think a pipe is frozen?","answer":"Keep the tap open, and if you can find the main shutoff valve, know where it is in case a pipe splits. Do not use an open flame to thaw a pipe. Request service and describe what you see."},{"question":"What if a pipe has already burst?","answer":"Close the main water shutoff, turn off the power if water is near electrical equipment and request service right away. Choose the Emergency option on the request form."},{"question":"How can I help prevent frozen pipes?","answer":"Keep the heat on, let a tap drip during very cold nights, open cabinet doors on exterior walls and disconnect outdoor hoses. See our guide to what to do when a pipe freezes."}]}},{"id":"44ee9ebe-40f9-465b-8e98-e79ad8e71e2f","type":"linkList","data":{"heading":"Frozen Pipe Repair in Denver & Boulder","links":[{"label":"Frozen Pipe Repair in Denver","href":"/denver"},{"label":"Frozen Pipe Repair in Boulder","href":"/boulder"},{"label":"Plumbing Services","href":"/plumbing"}]}},{"id":"82cb431b-59df-473a-8ca9-0e9caf29d51b","type":"cta","data":{"heading":"Need a Plumbing or HVAC Professional?","text":"Tell us what you need and find a local professional serving Denver or Boulder.","buttons":[{"label":"Request Service","href":"/book-service?category=plumbing&service=frozen-pipe-repair","variant":"primary"}],"tone":"dark"}}]$cms_seed$::jsonb,
