      $cms_seed$What to Do When a Pipe Freezes$cms_seed$,
      $cms_seed$resources/what-to-do-when-a-pipe-freezes$cms_seed$,
      $cms_seed$A frozen pipe can split when the ice thaws or expands. These steps help you limit the damage while you get help.$cms_seed$,
      $cms_seed$[{"id":"4d8cc906-a784-4e0f-8ce5-9930bb2c7c3c","type":"hero","data":{"eyebrow":"Helpful guide","heading":"What to Do When a Pipe Freezes","subtitle":"A frozen pipe can split when the ice thaws or expands. These steps help you limit the damage while you get help.","intro":"","image":"/art/home-pro.svg","buttons":[{"label":"Request Service","href":"/book-service","variant":"primary"}],"align":"left"}},{"id":"ba943453-5d37-4f0c-8e44-266befd03cc2","type":"contentBlock","data":{"label":"","heading":"Signs of a frozen pipe","imagePosition":"none","image":"","imageAlt":"","content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No water, or only a trickle, from a tap in cold weather"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Frost on exposed pipe"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A pipe that looks bulged or cracked"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Strange smells from a drain or tap"}]}]}]}]},"button":null}},{"id":"64331a94-7dad-44e4-8c27-43d0dc27c671","type":"contentBlock","data":{"label":"","heading":"What to do first","imagePosition":"none","image":"","imageAlt":"","content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the affected tap so water can flow as the ice melts"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find your main water shutoff valve so you can close it quickly if a pipe splits"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Warm the area with the heating on and cabinet doors open"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Never use an open flame to thaw a pipe"